# 🟢 低风险：只读/信息收集，通常无副作用
# ========== 1. CoreDNS部署检查 ==========
# 检查CoreDNS Pod状态
kubectl get pods -n kube-system -l k8s-app=kube-dns

# 查看CoreDNS详细信息
kubectl describe pods -n kube-system -l k8s-app=kube-dns

# 检查CoreDNS Service
kubectl get service -n kube-system kube-dns

# 验证Service endpoints
kubectl get endpoints -n kube-system kube-dns

# ========== 2. CoreDNS配置检查 ==========
# 查看CoreDNS ConfigMap
kubectl get configmap -n kube-system coredns -o yaml

# 检查CoreDNS配置文件
kubectl get configmap -n kube-system coredns -o jsonpath='{.data.Corefile}'

# 验证DNS服务IP
kubectl get service -n kube-system kube-dns -o jsonpath='{.spec.clusterIP}'

# ========== 3. DNS服务发现检查 ==========
# 检查kubelet DNS配置
kubectl get nodes -o jsonpath='{
    range .items[*]
}{
        .metadata.name
}{
        "\t"
}{
        .status.nodeInfo.osImage
}{
        "\n"
}{
    end
}'

# 验证节点DNS配置
for node in $(kubectl get nodes -o jsonpath='{.items[*].metadata.name}'); do
    echo "=== Node: $node ==="
    kubectl debug node/$node --image=busybox -it -- sh -c "cat /etc/resolv.conf"
done
